function Kaufman_spiral() {
    const roni_palette_col = [
        [171, 205, 94], [20, 151, 107], [43, 103, 175], [98, 182, 222],
        [245, 137, 163], [239, 86, 47], [252, 132, 5], [249, 213, 49]
    ]
    const roni_palette_bw = [color(5, 5, 5), color(255, 251, 230)]
    const roni_palettes = [roni_palette_col, roni_palette_bw]

    background(80);

    const rad_init = S / 29.8
    const n = 32; // number of angular divisions
    const theta = PI / n;
    const a = tan(theta) / sqrt(1 + sq(tan(theta)));
    const diam_init = 2 * rad_init * a
    const s2 = s * sqrt(2)
    const ff = 0.566

    translate(s, s)

    fill(roni_palette_bw[0])
    circle(0, 0, 2 * rad_init + diam_init)

    const scheme_switch_X = mX < 0.5
    const scheme_switch_Xmid = mX > 0.25 && mX < 0.75
    const scheme_switch_Y = mY < 0.5
    const scheme_switch_Ymid = mY > 0.25 && mY < 0.75
    const scheme_switch_X2 = mX2 < 0.5
    const scheme_switch_Y2 = mY2 < 0.5
    const scheme_switch_XY2 = scheme_switch_X2 && scheme_switch_Y2

    push()
    rotate(theta)
    let angle = 0
    let count_offset = 0
    let palette, len
    const dir = scheme_switch_Y2 ? 1 : -1
    for (let i = 0; i < n; i++) { // rotational loop
        push()
        let count = (i + 1) % 2
        if (scheme_switch_X) {
            palette = roni_palettes[count]
            len = palette.length
        }
        if (scheme_switch_Y) count_offset += count
        else count_offset += 1
        count_offset += scheme_switch_Xmid

        let rad = rad_init
        let diam = diam_init
        rad += (rad + diam * ff) * a
        rotate(angle)
        let count2 = 0
        let _wG_1 = 0; while ((rad < s2) && ++_wG_1 < 20000) { // translational loop
            if (!scheme_switch_X) {
                palette = roni_palettes[(count + count_offset * scheme_switch_Ymid) % 2]
                len = palette.length
            }
            count++
            count2++
            diam = 2 * rad * a

            if (len > 2) {
                // four color patterns: spiral, reverse spiral, radial, circular. Uses X2, Y2 to switch
                fill(palette[int((i * !scheme_switch_XY2 + !scheme_switch_X2 * dir * count2) / 2 + scheme_switch_XY2 * count2 + 1e3) % len])
            }
            else {
                fill(palette[(scheme_switch_Ymid * int(count2 / 2) * i + count + count_offset * (scheme_switch_Y || !scheme_switch_Ymid) + 1e3) % len])
            }
            circle(0, rad, diam);
            rad += 2 * (rad + diam * ff) * a
        }
        angle += 2 * theta
        pop()
    }
    pop()
    if (!revealed || fade_timer) {
        // top layer, just black and white
        for (let i = 0; i < n; i++) {
            let rad = rad_init
            let diam = diam_init
            let count = i % 2;
            rotate(2 * theta);
            let _wG_2 = 0; while ((rad < s2) && ++_wG_2 < 20000) {
                diam = 2 * rad * a
                const fill_col = roni_palette_bw[(count++) % 2]
                if (fade_timer) fill_col.setAlpha(fade_value)
                fill(fill_col)
                // fill(roni_palette_bw[(count++)%2]);
                circle(0, rad, diam);
                rad += 2 * (rad + diam * ff) * a
            }
        }
    }
}
