function distorted_square_rings() {
    noStroke()
    const n1 = 8
    const w = S / (n1 + 1);
    const w_mod = w * map(mX, 0, 1.5, 0.8, 1)
    const w2 = w / 2
    const w22 = w2 / 2
    const dir = (mY < 0.5) ? 1 : -1

    const shade1 = 255 * mX2
    const shade2 = 255 * (1 - mX2)

    rectMode(CENTER)
    background(180)
    fill(0)
    translate(w, w)
    for (let i = 0; i < n1; i++) {
        const x = i * w
        for (let j = 0; j < n1; j++) {
            if (!(i == 0 || j == 0 || i == n1 - 1 || j == n1 - 1)) continue
            const y = j * w
            const col = (i % 2 !== j % 2) ? shade1 : shade2
            fill(col)
            push()
            rect(x, y, w_mod)
            rect(x - w22, y - w22 * dir, w2)
            rect(x + w22, y + w22 * dir, w2)
            pop()
        }
    }

    const n2 = 5
    translate(w * 1.5, w * 1.5)
    for (let i = 0; i < n2; i++) {
        const x = i * w
        for (let j = 0; j < n2; j++) {
            if (!(i == 0 || j == 0 || i == n2 - 1 || j == n2 - 1)) continue
            const y = j * w
            const col = (i % 2 === j % 2) ? shade1 : shade2
            fill(col)
            push()
            rect(x, y, w_mod)
            rect(x - w22, y + w22 * dir, w2)
            rect(x + w22, y - w22 * dir, w2)
            pop()
        }
    }

    if (revealed || fade_timer) {
        resetMatrix()
        translate(s, s)
        noFill()
        stroke(200, 0, 0, 255 - fade_value)
        strokeWeight(w * 0.4)
        rect(0, 0, (n1 + 0.5) * w)
        rect(0, 0, (n2 + 0.5) * w)
        rect(0, 0, (n2 - 2.5) * w)
    }
}

