function Wilcox_twist() {
    noStroke()
    if (revealed) {
        background(150, 210, 255)
        fill(125, 80, 10)
    }
    else {
        background(255)
        fill(0)
    }

    const n1 = 24
    const angle_increment = TAU / n1
    const ray_width = s * 0.1325
    translate(s, s)

    for (let angle = 0; angle < PI; angle += (Math.max(0.001, Math.abs(angle_increment)) || 1)) {
        push()
        rotate(angle)
        beginShape()
        vertex(ray_width, -S)
        vertex(-ray_width, -S)
        vertex(ray_width, S)
        vertex(-ray_width, S)
        endShape(CLOSE)
        pop()
    }

    circle(0, 0, s * 0.2 * 0.8)
    const angle_shift = angle_increment * mX

    const mR = s * mY

    let r1 = s * 0.95
    let dir = 1
    const fill_col = revealed ? [235, 190, 100] : 255
    let _wG_6 = 0; while ((r1 > s * 0.08) && ++_wG_6 < 20000) {

        const r2 = r1 * 0.9

        let temp_coord_1, temp_coord_2

        if (r1 < mR) dir *= -1

        for (let angle = -angle_increment / 4; angle < TAU; angle += (Math.max(0.001, Math.abs(angle_increment)) || 1)) {
            const dir_angle = dir * angle

            beginShape()
            if (temp_coord_1) vertex(...temp_coord_1)
            else vertex(r1 * Math.cos(dir_angle), r1 * Math.sin(dir_angle))
            const angle2 = dir_angle + dir * angle_shift
            if (temp_coord_2) vertex(...temp_coord_2)
            else vertex(r2 * Math.cos(angle2), r2 * Math.sin(angle2))
            const angle_inc2 = dir * angle_increment / 2
            const angle3 = angle2 + angle_inc2
            temp_coord_2 = [r2 * Math.cos(angle3), r2 * Math.sin(angle3)]
            vertex(...temp_coord_2)
            const angle4 = dir_angle + angle_inc2
            temp_coord_1 = [r1 * Math.cos(angle4), r1 * Math.sin(angle4)]
            vertex(...temp_coord_1)
            endShape(CLOSE)

            push()
            fill(fill_col)
            beginShape()
            vertex(...temp_coord_1)
            vertex(...temp_coord_2)

            const angle5 = angle3 + angle_inc2
            temp_coord_2 = [r2 * Math.cos(angle5), r2 * Math.sin(angle5)]
            vertex(...temp_coord_2)
            const angle6 = angle4 + angle_inc2
            temp_coord_1 = [r1 * Math.cos(angle6), r1 * Math.sin(angle6)]
            vertex(...temp_coord_1)
            endShape(CLOSE)
            pop()
        }
        r1 *= 0.8
    }
}
