function Metamere_twisted_cord() {

    if (!final_refresh && canv_mult == 1 && density > 2) {
        setup(false, 2)
        return
    }
    refresh_delay = 2 * mobile // keeps it from stuttering
    background(127 * mX2);
    translate(s, s)

    let diam_limit = final_refresh || mY2 === 0 ? 5 : S / 9 // reduces calculation requirements significantly while animating
    let d2 = S * 1.414
    const f = 0.075 + 0.1 * mY
    const n1 = 30
    const angle_increment = TAU / n1
    const sub_increments = 35
    const wt_factor = 1 / (18 * sub_increments)
    const angle_increment2 = 1.3 * angle_increment / sub_increments * mY
    const angle_increment3 = angle_increment * 2.5 * mX
    const angle_increment4 = angle_increment * (0.5 - 0.15 * mY)

    noFill()
    let _wG_7 = 0; while ((d2 > diam_limit) && ++_wG_7 < 20000) {
        rotate(angle_increment3)
        const wt_temp = d2 * wt_factor
        const wt_temp_Y = wt_temp * mY2
        strokeWeight(wt_temp_Y)

        const diam2 = d2 / n1
        const fd = 0.993 + 0.0045 * mX
        const fd_total = pow(fd, sub_increments)
        for (let i = 0; i < n1; i++) {
            rotate(angle_increment)
            push()
            fill(255 * (i % 2 == 0))
            rotate(-angle_increment4)
            circle(d2 * 0.5, 0, diam2)
            pop()
            let d3 = d2
            push()
            stroke(255 * (i % 2))
            if (mY2 > 0) {
                for (let j = 0; j < sub_increments; j++) {
                    d3 *= fd
                    rotate(angle_increment2)
                    arc(0, 0, d3, d3, 0, angle_increment)
                }
            }
            else {
                rotate(angle_increment2 * sub_increments)
                d3 *= fd_total
            }
            push()
            fill(255 * (i % 2))
            noStroke()
            rotate(angle_increment4)
            circle(d3 * 0.5, 0, diam2)
            pop()
            pop()
        }
        if (revealed) {
            push()
            strokeWeight(wt_temp * 5)
            stroke(255, 0, 0, 150)
            circle(0, 0, d2 * (2 - fd_total) - wt_temp * 5)
            pop()
        }
        d2 *= 1 - f
    }

    if (!final_refresh && mY2 > 0) {
        fill(25)
        circle(0, 0, diam_limit * 1.1)
    }
}

