function afterimage_spiral() {
    blendMode(BLEND)
    background(135)
    translate(s, s)

    let diam_limit = final_refresh ? 5 : S / 30
    let d2 = S * 1.414
    const f = 0.08 + 0.15 * mY
    const n1 = 12
    const angle_increment = TAU / n1
    const wt_factor = 0.015

    const diam_factor = 0.885

    const blur_amount = d2 * 0.005 * (1 - mY2)

    let _wG_8 = 0; while ((d2 > diam_limit) && ++_wG_8 < 20000) {
        rotate(mX)
        const wt_temp = d2 * wt_factor
        // noStroke()
        push()
        beginClip()
        circle(0, 0, d2)
        endClip()

        beginClip({ invert: true })
        circle(0, 0, d2 - wt_temp * 10)
        endClip()

        fill(255)

        for (let i = 0; i < n1; i++) {
            push()
            if (i % 2 == 1) fill(0)
            rotate(angle_increment * i)
            translate(d2 * (1 - diam_factor), 0)
            beginClip({ invert: true })
            circle(0, d2 * (0.09 - 0.075 * (1 - mX2)), d2 * (diam_factor + 0.019))
            endClip()
            circle(0, 0, d2 * diam_factor)
            pop()
        }
        pop()
        if (revealed) {
            push()
            strokeWeight(wt_temp)
            stroke(255, 0, 0, 150)
            noFill()
            circle(0, 0, d2 + wt_temp)
            pop()
        }
        d2 *= 1 - f
    }
    if (blur_amount > 0) filter(BLUR, blur_amount)
}

