function brightness_shift_rings() {

    if (initialize_illusion) {
        pg1.resizeCanvas(S, S)
        pg1.noStroke()
        pg1.fill(0)
    }

    background(255/2)

    pg1.push()
    pg1.translate(s, s)

    let diam_limit = S * (0.08 - 0.03 * (1 - mX)) * (1 + mobile)
    let d2 = S * 1.435
    const blur_amount = diam_limit * 0.06 * (1 - mY)

    count = 0
    let _wG_9 = 0; while ((d2 > 0) && ++_wG_9 < 20000) {
        noStroke()
        pg1.push()
        if(d2 > diam_limit/2){
            pg1.beginClip({ invert: true })
            pg1.circle(0, 0, d2 - diam_limit / 2)
            pg1.endClip()
            pg1.circle(0, 0, d2)
            pg1.fill(255)
            pg1.circle(0, 0, d2 - diam_limit / 4)
        }
        else pg1.circle(0, 0, d2)
        pg1.pop()
        d2 -= diam_limit
    }
    pg1.pop()

    image(pg1,0,0)
    push()
    blendMode(DIFFERENCE)
    rectMode(CORNERS)
    fill(255)
    rect(0,0,s,s)
    rect(s,s,S,S)
    pop()
    if (blur_amount > 0) filter(BLUR, blur_amount)
    pg1.clear()
}

