function Pinna_intertwining() {
    translate(s, s)
    background(155)
    noFill()
    rectMode(CENTER)
    n_layers = 5 + max(0, int((S - 600) / 100))
    const rect_size = S / (n_layers + 1) / 6
    const max_diam = S - rect_size * 2
    strokeWeight(rect_size / 10)
    const wt2 = rect_size * 0.33

    for (let layer = 1; layer <= n_layers; layer++) {
        let layer_ratio = layer / n_layers
        const diam = layer_ratio * max_diam
        const circumference = PI * diam
        let rect_count = Math.floor(circumference / (rect_size * 1.75))

        rect_count += (rect_count % 2 === 1) // ensure it's even so the color always alternates

        let angle_step = TAU / rect_count
        rotate(angle_step * 0.5)

        const angle_shift = PI / 10 * (2 * (layer % 2) - 1) * (mX + (mX > 1) * 2 * (mX - 1))
        const shade = 255 * mY
        for (let i = 0; i < rect_count; i++) {
            push()
            stroke((i % 2) * shade)
            rotate(angle_step * i)
            translate(diam / 2, 0)
            rotate(angle_shift)
            rect(0, 0, rect_size)
            pop()
        }

        if (revealed) {
            push()
            strokeWeight(wt2)
            stroke(255, 0, 0, 100)
            circle(0, 0, diam - wt2 * 10)
            pop()
        }
    }
}
