function rotating_snakes() {
    bg_color = color(255, 245, 245)
    background(bg_color)
    const n = 2 + (S > 700)
    let diam = S / n
    let diam_limit = final_refresh ? 1 : diam / 70
    let c1 = color(160, 210, 60)
    let c2 = color(150, 150, 240)

    if (initialize_illusion) {
        pg1.resizeCanvas(S, S)
        pg1.noStroke()
        pg1.fill(bg_color)
    }

    pg1.push()
    pg1.rectMode(CENTER)
    pg1.translate(diam / 2, diam / 2)
    let r2 = diam / 2
    let f = 0.1 + 0.1 * mY
    let n1 = 23
    let angle_increment = TAU / n1
    pg1.circle(0, 0, diam)
    let _wG_10 = 0; while ((r2 > diam_limit) && ++_wG_10 < 20000) {
        let d = r2 * f
        let d2 = d * 0.3
        pg1.rotate(angle_increment * 0.5 * mX)

        for (let i = 0; i < n1; i++) {
            pg1.rotate(angle_increment)
            pg1.push()
            pg1.translate(0, r2 - d / 2)
            pg1.fill(0)
            pg1.rect(0, 0, 2 * d2, d)
            pg1.fill(c1)
            pg1.ellipse(d2, 0, d * 0.45, d)
            pg1.fill(c2)
            pg1.ellipse(-d2, 0, d * 0.45, d)
            pg1.pop()
        }
        r2 *= 1 - f
    }
    pg1.pop()

    push()
    translate(-diam / 2, -diam / 2)
    for (let i = 0; i <= n; i++) {
        for (let j = 0; j <= n; j++) {
            image(pg1, i * diam, j * diam)
        }
    }
    pop()
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            image(pg1, i * diam, j * diam)
        }
    }
    pg1.clear()
}
