function rotating_rings() {
    bg_col = color(150)
    c1 = color(100)
    c2 = color(230)

    background(bg_col)
    rectMode(CENTER)
    let rad1 = s * 1.02

    let d_diam = rad1 / 9 * mX
    let shift_angle = PI * 0.19 * mY

    translate(s, s)
    fill(0)
    circle(0, 0, S / 50)
    circ(rad1 * 0.9 * mX, 1)
    circ(rad1 * 0.73 * mX, -1)
    d_diam = rad1 / 11 * mX
    circ(rad1 * 0.55 * mX, 1)
    d_diam = rad1 / 12 * mX
    circ(rad1 * 0.4 * mX, -1)

    if (revealed) {
        push()
        stroke(255, 0, 0, 100)
        const n = 12
        const inner = S / 50
        const angle_increment = TAU / n
        for (let i = 0; i < n; i++) {
            rotate(angle_increment)
            line(inner, 0, S, 0)
        }
        pop()
    }

    function circ(rad, rotation_direction) {
        push()
        const n1 = int(2.8 * int(rad / d_diam) + 10)
        diamond_ring(rad, n1, 0, 1, rotation_direction, c1)
        diamond_ring(rad, n1, -0.04, 0.905, rotation_direction, c2)
        diamond_ring(rad, n1, 0, 0.83, rotation_direction, bg_col)
        pop()
    }
    function diamond_ring(rad, n, shift, scale_amt, rotation_direction, col) {
        const angle_increment = TAU / n
        const shift_angle2 = shift_angle * rotation_direction
        fill(col)
        for (let i = 0; i <= n; i++) {
            rotate(angle_increment)
            push()
            translate(rad, 0)
            rotate(shift_angle2)
            translate(shift * d_diam, 0)
            scale(0.65, 1)
            scale(scale_amt, scale_amt)
            rotate(QUARTER_PI)
            rect(0, 0, d_diam)
            pop()
        }
    }
}

