function distorted_rings() {
    background(170)

    const rad1 = 0.9 * s
    const scale_factor = 8
    const bw = s / scale_factor
    const bw2 = bw / 2

    if (initialize_illusion) {
        pg1.resizeCanvas(bw, bw)
        pg1.rectMode(CENTER)
        pg1.noStroke()
        noSmooth()
    }

    translate(s, s)

    const blur_amount = 13.5 * S / 1440 * mX2
    const n2 = 70
    const n22 = n2 / 2
    const angle_increment = TAU / n2
    const shift_mag = bw * 1.1 * mY
    const rot = HALF_PI + PI * mX

    push()
    rotate(-rot)
    distorted_ring(rad1, 0.0785 * scale_factor)
    pop()

    rotate(rot)
    distorted_ring(rad1 * 0.77, 0.061 * scale_factor)

    function distorted_ring(rad, scale_amt) {
        const translation_array = [rad - bw2 * scale_amt, - bw2 * scale_amt]
        const bw6 = bw * 0.65
        const separation = bw * 0.75
        const diam = bw * 0.8 * mY2
        for (let i = 0; i < n2; i++) {
            const fraction = ((i + 2) % 5) / 4
            const shift = shift_mag * (i < n22 ? fraction : 1 - fraction)

            pg1.background(127)
            pg1.push()
            pg1.translate(shift, bw2)
            pg1.fill(255)
            pg1.ellipse(separation, 0, diam)
            pg1.ellipse(-separation, 0, diam)
            pg1.fill(0)
            pg1.ellipse(0, 0, bw6, bw * 0.85)
            pg1.pop()
            if (!(mobile && !final_refresh) && blur_amount > 0) pg1.filter(BLUR, blur_amount)

            push()
            rotate(angle_increment * i)
            translate(...translation_array)
            scale(scale_amt, scale_amt)

            image(pg1, 0, 0)
            pop()
        }
    }
    pg1.clear()
}

