function rotating_triangle_rings() {
    background(35, 35, 180)

    const rad1 = 0.9 * s

    const shift_angle = PI * 0.51 * min(mY, 1.96)

    const scale_factor = 8
    const bw = s / scale_factor
    const bh = bw * 0.65

    if (initialize_illusion) {
        pg1.resizeCanvas(bw, bh)
        pg1.noStroke()
    }

    pg1.push()
    linearGradient(
        pg1,
        0, 0, //Start point
        bw * max(mX, 0.01), 0, //End point
        color(140, 0, 0), //start color
        color(255), //end color
    )
    pg1.triangle(0, 0, 0, bh, bw, bh / 2)
    pg1.pop()

    translate(s, s)
    triangle_ring(rad1, 1, 0.12 * scale_factor)
    triangle_ring(rad1 * 0.6, -1, 0.09 * scale_factor)

    function triangle_ring(rad, rotation_direction, scale_amt) {
        const n = int(25 * rad / rad1 + 20)
        const angle_increment = TAU / n
        const translation_array = [- bw / 2 * scale_amt, - bh / 2 * scale_amt]
        const shift_angle2 = shift_angle * rotation_direction
        for (let i = 0; i <= n; i++) {
            rotate(angle_increment)
            push()
            translate(rad, 0)
            rotate(shift_angle2)
            translate(...translation_array)
            scale(scale_amt, scale_amt)
            image(pg1, 0, 0)
            pop()
        }
    }
    pg1.clear()
}

