function shifting_triangle_rings() {
    background(35, 35, 180)

    const grid_size = 3 + max(0, int((S - 600) / 350))
    const d = S / grid_size

    const t_diam = s * 0.15

    const shift_angle = PI * 0.53 * min(mY, 1.9)

    const scale_factor2 = 8
    const bw = s / scale_factor2
    const bh = bw * 0.65

    const scale_factor = d / s * scale_factor2

    if (initialize_illusion) {
        pg1.resizeCanvas(bw, bh)
        pg1.noStroke()
        pg2.resizeCanvas(s, s)
        pg3.resizeCanvas(s, s)
    }

    pg1.push()
    linearGradient(
        pg1,
        0, 0, //Start point
        bw * max(mX, 0.01), 0, //End point
        color(140, 0, 0), //start color
        color(255), //end color
    );
    pg1.triangle(0, 0, 0, bh, bw, bh / 2)
    pg1.pop()

    circ(pg2, 1)
    circ(pg3, -1)

    for (let i = 0; i < grid_size; i++) {
        const x_pos = i * d
        for (let j = 0; j < grid_size; j++) {
            push()
            translate(x_pos, j * d)
            if (i % 2 === j % 2) image(pg2, 0, 0)
            else image(pg3, 0, 0)
            pop()
        }
    }

    function circ(buffer, rotation_direction) {
        buffer.push()
        buffer.translate(d / 2, d / 2)
        triangle_ring(buffer, d * 0.4, rotation_direction, 0.185 * scale_factor)
        triangle_ring(buffer, d * 0.265, rotation_direction, 0.13 * scale_factor)
        triangle_ring(buffer, d * 0.16, rotation_direction, 0.08 * scale_factor)
        buffer.pop()
    }

    function triangle_ring(buffer, rad, rotation_direction, scale_amt) {
        const n = int(2 * int(rad / t_diam) + 11)
        const angle_increment = TAU / n
        const translation_array = [- bw / 2 * scale_amt, - bh / 2 * scale_amt]
        const shift_angle2 = shift_angle * rotation_direction
        buffer.push()
        buffer.rotate(TAU * int(rad / t_diam))
        for (let i = 0; i <= n; i++) {
            buffer.rotate(angle_increment)
            buffer.push()
            buffer.translate(rad, 0)
            buffer.rotate(shift_angle2)
            buffer.translate(...translation_array)
            buffer.scale(scale_amt, scale_amt)
            buffer.image(pg1, 0, 0)
            buffer.pop()
        }
        buffer.pop()
    }

    pg1.clear()
    pg2.clear()
    pg3.clear()
}
