function shifting_rings() {
    const bg_col = color(100, 100, 255)
    const c1 = color(255 * (1 - mX))
    const c2 = color(255 * mX)

    background(bg_col)

    const shift_angle = PI * 0.5 * mY

    const grid_size = 3 + max(0, int((S - 600) / 200))
    const d = S / grid_size
    const rad = d * 0.64 / 2
    const diam2 = rad / 1.75
    const n1 = 8
    const angle_increment = TAU / n1

    if (initialize_illusion) {
        pg1.resizeCanvas(d, d)
        pg2.resizeCanvas(d, d)
        pg1.noStroke()
        pg2.noStroke()
    }

    circ(pg1, 1, [245, 130, 0])
    circ(pg2, -1, [225, 185, 30])

    for (let i = 0; i < grid_size; i++) {
        const x_pos = i * d
        for (let j = 0; j < grid_size; j++) {
            push()
            translate(x_pos, j * d)
            if (i % 2 === j % 2) image(pg1, 0, 0)
            else image(pg2, 0, 0)
            pop()
        }
    }

    function circ(buffer, translate_direction, inner_col) {
        buffer.push()
        buffer.rectMode(CENTER)
        buffer.translate(d / 2, d / 2)
        diamond_ring(buffer, 0, 1, c1)
        diamond_ring(buffer, translate_direction * 0.05, 0.89, c2)
        diamond_ring(buffer, 0, 0.79, inner_col)
        buffer.pop()
    }

    function diamond_ring(buffer, shift, scale_amt, col) {

        buffer.fill(col)
        for (let i = 0; i <= n1; i++) {
            buffer.rotate(angle_increment)
            buffer.push()
            buffer.translate(rad, 0)
            buffer.rotate(shift_angle)
            buffer.translate(shift * diam2, 0)
            buffer.scale(0.65, 1)
            buffer.scale(scale_amt, scale_amt)
            buffer.rotate(QUARTER_PI)
            buffer.rect(0, 0, diam2, diam2, diam2 / 6)
            buffer.pop()
        }
    }

    pg1.clear()
    pg2.clear()
}

