function distorted_square() {
    background(230, 255, 240)
    noFill()
    stroke(0)
    rectMode(CENTER)
    translate(s, s)

    const divisions = (10 + S / 150) * mX * (1 + max(0, mX - 1))
    const diam = S * 0.95

    strokeWeight(wt * 2)
    rotate(QUARTER_PI)
    let rect_size = diam * 0.627
    rect(0, 0, rect_size)

    strokeWeight(wt * 0.6 * mY)

    const diam_min = diam * 0.45
    const increment = (diam - diam_min) / divisions
    const diam_inc = diam_min + increment
    for (let i = diam; i > diam_min; i -= increment) {
        if (i < diam_inc) stroke(0, 255 * (i - diam_min) / increment)
        circle(0, 0, i)
    }
}
