function shimmer() {
    if (!final_refresh && canv_mult == 1 && density > 2) {
        setup(false, 2)
        return
    }

    if (initialize_illusion) {
        pg1.resizeCanvas(S, S)
        pg2.resizeCanvas(S, S)
        mask_layer.resizeCanvas(S, S)

        mask_layer.noFill()
        mask_layer.stroke(0)
        mask_layer.translate(s, s)
        mask_layer.rotate(QUARTER_PI)

        pg1.noStroke();
        pg1.fill(0)
        noSmooth()
    }

    let diam = S * 1.2
    const cols = max(0, 2 + (100 + S * 0.15) * mX)
    const col_S = S / cols

    pg1.background(255)
    pg1.push()

    pg1.translate(s, 0)
    for (let i = 0; i < cols / 2; i++) {
        pg1.rect(i * col_S * 2, 0, col_S, S);
        pg1.rect((-1 - i) * col_S * 2, 0, col_S, S);
    }
    pg1.pop()

    image(pg1, 0, 0) // draw image 1 to canvas

    translate(s, s)
    rotate(HALF_PI)
    translate(-s, -s)

    let sw = S * 0.09

    mask_layer.push()
    mask_layer.rectMode(CENTER)
    let _wG_11 = 0; while ((diam > sw) && ++_wG_11 < 20000) {
        mask_layer.strokeWeight(sw)
        mask_layer.rect(0, 0, diam * mY)
        sw *= 0.8
        diam -= sw * 4
    }

    mask_layer.circle(0, 0, diam + sw)

    mask_layer.erase() // when erase is set, shapes sets area to transparent. use noErase() method to switch back.

    pg2.image(pg1, 0, 0) // paste a quarter turned version of image 1 into image 2
    pg2.push()
    // this command sets the layer to receive the masking operation
    // https://developer.mozilla.org/en-US/docs/Web/API/CanvasRenderingContext2D/globalCompositeOperation
    pg2.drawingContext.globalCompositeOperation = 'destination-in'
    pg2.image(mask_layer, 0, 0) // paste the mask layer into image 2 using the composite image operation

    pg2.pop()

    image(pg2, 0, 0) // draw image 2 to canvas
    mask_layer.pop()
    mask_layer.clear()
}
