function dazzle_tilt_zag() {
    if (!final_refresh && canv_mult == 1 && density > 2) {
        setup(false, 2)
        return
    }

    const c1 = revealed ? color(50, 110, 255) : 255
    const c2 = revealed ? color(140, 200, 80) : 0

    if (initialize_illusion) {
        pg1.resizeCanvas(S, S)
        pg1.noStroke();
        noSmooth()
    }
    pg1.fill(c2)

    const cols = max(0, 2 + (30 + S * 0.1) * mX2)
    const col_S = S / cols

    pg1.background(c1)
    pg1.push()

    pg1.translate(s, 0)
    for (let i = 0; i < cols / 2; i++) {
        pg1.rect(i * col_S * 2, 0, col_S, S);
        pg1.rect((-1 - i) * col_S * 2, 0, col_S, S);
    }
    pg1.pop()

    image(pg1, 0, 0) // draw image 1 to canvas

    const grid_size = 8 // 4 + max(0, int((S-600)/200))
    const d = S / grid_size
    const d2 = d / 2
    let diam = d * (mY) * 6

    const default_angle = QUARTER_PI * 0.97

    push()
    blendMode(DIFFERENCE)
    translate(d2, d2)
    rectMode(CENTER)
    fill(255 * mY2)
    for (let i = 0; i < grid_size; i++) {
