function Ouchi() {
    if (!final_refresh && canv_mult == 1 && density > 2) {
        setup(false, 2)
        return
    }
    const rows = 40 * (1 + 5 * (1 - mY2))
    const row_ht = S / rows
    const circle_diam = S / 40 * 24 * mY
    const cols = max(0, rows * (1 - 0.75 * mX))
    const col_S = S / cols

    if (initialize_illusion) {
        pg1.resizeCanvas(S, S)
        pg2.resizeCanvas(S, S)
        pg3.resizeCanvas(S, S)
        pg2.fill(255)
        noSmooth()
    }
    pg1.push()
    pg1.background(255)
    pg1.noStroke();
    pg1.fill(0)
    for (let i = 0; i < rows; i++) {
        pg1.rect(0, i * row_ht * 2, S, row_ht);
    }
    pg1.pop()

    pg2.image(pg1, 0, 0)

    pg2.push()
    pg2.blendMode(DIFFERENCE)
    pg2.translate(s, 0)

    for (let i = 0; i < cols / 2; i++) {
        pg2.rect(i * col_S * 2, 0, col_S, S);
        pg2.rect((-1 - i) * col_S * 2, 0, col_S, S);
    }
    pg2.pop()

    image(pg2, 0, 0)

    if (mY > 0.01) {
        translate(s, s)
        rotate(HALF_PI + mX2 * 3 * TAU)
        translate(-s, -s)
        pg3.push()
        pg3.beginClip()
        pg3.circle(s, s, circle_diam) // set clipping shape. Everything outside the circle will be excluded.
        pg3.endClip()
        pg3.image(pg2, 0, 0) // paste a quarter turned version of image
        pg3.pop()
        image(pg3, 0, 0)
        pg3.clear()
    }
}
