function Popple_Rows() {
    noStroke()
    blendMode(BLEND)
    rectMode(CENTER)
    background(180)

    const n1 = int(9 + (1 - mX2) * 11)
    const n2 = int(4 + (1 - mY2) * 5)
    const d1 = S / (n1 + 0.5)
    const d2 = S / (n2 + 0.5)
    const diam = S / (13 * (2 - mX2))
    const blur_amount = diam * 0.13 * mY

    const col1 = 255 * mX
    const col2 = 255 * (1 - mX)
    fill(col1)

    for (let i = 0; i < n1; i++) {
        const id2 = (i + 0.75) * d1
        for (let j = 0; j < n2; j++) {
            push()
            const jd2 = (j + 0.75) * d2
            translate(id2, jd2)
            if (i % 2 == 0) {
                if (i % 4 == 0) rotate(PI)
                arc(0, 0, diam, diam, 0, PI, PIE)
                fill(col2)
                rotate(PI)
                arc(0, 0, diam, diam, 0, PI, PIE)
            }
            else {
                const alt = (i + 1 + 2 * (j % 2)) % 4 == 0
                if (alt) fill(col2)
                circle(0, 0, diam)
                push()
                beginClip()
                rect(0, 0, diam + 1, diam * 0.4)
                endClip()
                fill(alt ? col1 : col2)
                circle(0, 0, diam + 1)
                pop()
            }
            pop()
        }
    }
    if (blur_amount > 0) filter(BLUR, blur_amount)
}

