function bulging_grid() {
    const mX_temp = max(mX, 0.001)
    const n1 = 15
    const w = S / n1
    const w2 = w / 2
    const margin = w / 25
    const w_small = (w - 2 * margin) / 3
    const p = 3 - 2 * mX_temp
    const wX = w_small * max(1, p)
    const rad = S * (0.5 * mY - 0.08)
    const rad_small = w_small / 2 * max(0, 1.25 - mX_temp)
    rectMode(CENTER)
    background(255)
    fill(0)
    for (let i = 0; i < n1; i++) {
        const x = i * w
        const x2 = x + w2
        const x_shift = abs(x2 - s) < w2 ? 0 : round_away((x2 - s) / s) * w_small * mX_temp
        for (let j = 0; j < n1; j++) {
            const y = j * w
            const y2 = y + w2
            const y_shift = abs(y2 - s) < w2 ? 0 : round_away((y2 - s) / s) * w_small * mX_temp
            let col = 0
            if (i % 2 === j % 2) {
                push()
                rectMode(CORNER)
                rect(x, y, w) // checkerboard rectangles, only need to draw the black ones
                col = 255
                pop()
            }
            if (dist(s, s, x2, y2) < rad) {
                push()
                fill(col)
                if (!(x_shift == 0 && y_shift == 0)) {
                    if (x_shift == 0 || y_shift == 0) translate(-x_shift, -y_shift)

                    rect(x2 + y_shift, y2 - x_shift, wX, wX, rad_small)
                    rect(x2 - y_shift, y2 + x_shift, wX, wX, rad_small)
                }
                pop()
            }
        }
    }
    if (mX < 0.75 && rad > 0) { // center square, only appears when the others are large enough that it would be missed
        fill(255)
        const w3 = w_small * 3 * min(1, map(mX, 0.75, 0.5, 0, 1))
        rect(s, s, w3, w3, rad_small)
    }
}
