function expand_contract_grid() {
    const mY_temp = max(0.25, mX) * 2.25
    const mX_temp = max(0, map(mX, 0, 1, 1, 0))
    const n1 = 13
    const w = S / n1
    const w_small = w / 6 * map(mY_temp, 0.5, 3, 1.25, 0.5)
    rectMode(CENTER)
    background(255 - 95 * mY)
    fill(120 * mY)
    for (let i = 0; i < n1; i++) {
        const x = i * w
        const x_side = x - s > 0
        for (let j = 0; j < n1; j++) {
            const y = j * w
            const y_side = y - s > 0
            const ij_mod2_equal = i % 2 === j % 2
            if (ij_mod2_equal) {
                push()
                rectMode(CORNER)
                rect(x, y, w)
                pop()
            }

            if (i > 0 && j > 0) {
                push()
                fill(!((ij_mod2_equal && x_side === y_side) || (!ij_mod2_equal && (x_side !== y_side))) * 255)
                bez_shape(x, y, w_small, mY_temp)
                pop()
            }
        }
    }
    stroke(140)
    strokeWeight(wt / 2 * mX_temp)
    for (let i = 1; i < n1; i++) {
        const d = i * w
        line(d, w, d, S - w)
        line(w, d, S - w, d)
    }
}
