function bez_shape(x, y, d, coeff) {
    push()
    translate(x, y)
    rotate(QUARTER_PI)

    const d2 = d * coeff
    beginShape()
    vertex(d, 0)
    bezierVertex(d, 0 + d2, 0 + d2, d, 0, d)
    bezierVertex(0 - d2, d, -d, 0 + d2, -d, 0)
    bezierVertex(-d, 0 - d2, 0 - d2, -d, 0, -d)
    bezierVertex(0 + d2, -d, d, 0 - d2, d, 0)
    endShape()
    pop()
}
