function anomalous_motion() {
    const mX_temp = max(0.5, mX) * 2
    const mY_temp = constrain(map(mY, 0, 2, -1, 1) * S/4, -S/4, S/4)
    const n1 = 25 - 8 * mobile
    const w = S / n1
    const w_small = w * 0.225 * map(mX_temp, 0.5, 3, 1.25, 0.5)
    const ww = max(w/8, w_small * 2)
    const wh = ww * 0.5
    const w_skew = w_small * 0.4
    const band_w = ~~(n1/4)
    const blur_amount = w_skew
    rectMode(CENTER)
    strokeWeight(max(1, wh / 3))
    background(150)
    translate(0, mY_temp)
    for (let i = 0; i < n1; i++) {
        const x = i * w
        for (let j = 0; j < n1; j++) {
            if (i > 0 && j > 0 ) {

                const inner = i > band_w + 1 && i < n1 - band_w - 1 && j > band_w + 1 && j < n1 - band_w - 1

                if(i > band_w && i < n1 - band_w && j > band_w && j < n1 - band_w && !inner) continue

                const y = j * w
                const ij_mod2_equal = i % 2 === j % 2
                const orient = inner ? ij_mod2_equal + 0.5 : ij_mod2_equal
                const skew_dir = inner ? 1 : -1
                push()
                translate(x, y)
                if(mX > 0){

                    push()
                    if(i < n1 - 1 && !(i > band_w - 1 && i < n1 - band_w && j > band_w && j < n1 - band_w) ||
                    (inner && i < n1 - band_w - 2)){
                        stroke(ij_mod2_equal * 255)
                        line(0,skew_dir * w_skew,w,-skew_dir * w_skew)
                    }
                    if(j < n1 - 1 && !(i > band_w && i < n1 - band_w && j > band_w - 1 && j < n1 - band_w) ||
                    (inner && j < n1 - band_w - 2)){
                        if(inner) stroke(ij_mod2_equal * 255)
                            else stroke((1 - ij_mod2_equal) * 255)
                        line(skew_dir * w_skew,0,-skew_dir * w_skew,w)
                    } 
                    pop()
                }

                rotate(PI * orient + QUARTER_PI)
                fill(255)
                if(revealed && mX < 1.5) ellipse(0,wh/2,ww, wh)
                else rect(0,wh/2,ww, wh)
                fill(0)
                rotate(PI)
                if(revealed && mX < 1.5) ellipse(0,wh/2,ww, wh)
                else rect(0,wh/2,ww, wh)
                pop()
            }
        }
    }
    if(!revealed) filter(BLUR, blur_amount)
}

