function anomalous_motion2() {
    const mY_temp = constrain(map(mY, 0, 2, -1, 1) * S/4, -S/4, S/4)
    const n1 = 25 - 8 * mobile
    const w = round(S / n1)
    const w2 = w/2
    const w3 = w2 * constrain(map(mX, 0,2, 2.5,0) + 0.75,0,2.25)
    const band_w = ~~(n1/4) - 1
    const blur_amount = (1 - mY2 - (2.5 - mX) / 3) * S * 0.008
    rectMode(CENTER)
    background(150)
    translate(0, mY_temp)
    for (let i = 0; i < n1-1; i++) {
        const x = i * w
        for (let j = 0; j < n1-1; j++) {
            if(revealed && i > band_w - 1 && i < n1 - band_w - 1 && j > band_w - 1 && j < n1 - band_w - 1 && 
                !(i > band_w + 1 && i < n1 - band_w - 2 && j > band_w + 1 && j < n1 - band_w - 2)) continue

            const inner = i > band_w && i < n1 - band_w - 2 && j > band_w && j < n1 - band_w - 2
            const y = j * w
            let ij_mod2_equal = i % 2 === j % 2


            push()
            if(revealed && inner) translate(-w2,-w2)
            translate(x, y)
            if(inner){
                translate(w,w)
                rotate(HALF_PI)
                translate(-w,-w)
            }
            if(mX2 !== 1){
                translate(w,w)
                rotate(HALF_PI * (mX2 - 1) * (inner ? -1 : 1))
                translate(-w,-w)
            }
            translate(w, w)

            fill(ij_mod2_equal * 255)
            beginShape()
            vertex(0,0)
            vertex(0,w)
            bezierVertex(0, w - w3,  w - w3, 0, w,0)
            endShape(CLOSE)

            fill((1 - ij_mod2_equal) * 255)
            rotate(PI)
            beginShape()
            vertex(0,0)
            vertex(0,w)
            bezierVertex(0, w - w3,  w - w3, 0, w,0)
            endShape(CLOSE)
            pop()
        }
    }
    if(blur_amount > 0 && mY2 < 1) filter(BLUR, blur_amount)
}

