function squiggly_squares() {
    background(255 - 25 * mY)
    let n1 = 15 + max(0, int((S - 600) / 80))
    n1 += (n1 % 2 === 0)
    let d1 = S / n1
    let d2 = d1 / 6 //* mX * mX
    let d3 = d1 * sqrt(2)

    fill(135 * mY)
    for (let i = 0; i < n1; i++) {
        for (let j = 0; j < n1; j++) {
            if (i % 2 === j % 2) {
                rect(i * d1, j * d1, d1)
            }
        }
    }
    if (d2 > 0) {
        let m_limit = n1 * 2 - 3
        let freq = 10.6 * mX
        translate(s - d1 / 2, -s - d1 / 2)
        // small pinwheels are same along diagonal lines from upper left to lower right, 
        //so it's easier to angle and draw the grid that way, but harder to constrain to central area.
        rotate(QUARTER_PI)
        translate(d3 - d2, d3 / 2 - d2)
        for (let m = 0; m < m_limit; m++) {
            let condition = sin(m * freq) * cos(m * freq) > 0.1
            translate(0, d3 / 2)
            push()
            let limit = n1 - 1
            if (m % 2 == 1) {
                translate(-d3 / 2, 0)
                limit++
            }
            for (let k = 1; k < limit; k++) {
                translate(d3, 0)
                for (let i = 0; i < 2; i++) {
                    for (let j = 0; j < 2; j++) {
                        if (i % 2 === j % 2) fill(255 * !condition)
                        else fill(255 * condition)
                        rect(i * d2, j * d2, d2)
                    }
                }
            }
            pop()
        }
    }
}
