function Ehrenstein() {
    background(255)
    const rt2 = sqrt(2)
    const n1 = 2 * (5 + max(0, int((S - 600) / 160)))
    const d2 = S / n1
    const wt2 = d2 * (0.06) * (mY < 1 ? mY : 1 + 5 * (mY - 1))
    const rad = max(3 * wt2, d2 * (1.935 - 1.05 * mX)) / 2

    strokeWeight(wt2)
    rectMode(CENTER)
    stroke(0)

    for (let i = 0; i <= n1; i++) {
        const id2 = i * d2
        line(0, id2, S, id2)
        line(id2, 0, id2, S)
        if (!revealed) {
            push()
            strokeWeight(wt2 * 0.7)
            translate(s, s)
            rotate(QUARTER_PI)
            scale(rt2, rt2)
            translate(-s, -s)
            line(0, id2, S, id2)
            line(id2, 0, id2, S)
            pop()
        }
    }

    noStroke()
    blendMode(LIGHTEST)
    randomSeed(seed)

    for (let i = 0; i <= n1; i++) {
        const id2 = i * d2
        for (let j = 0; j <= n1; j++) {
            if (i % 2 === j % 2) {
                const a = 255 - random(55)
                const b = 135 + random(80)
                fill(random([[b, a, 255], [255, a, b], [a, 255, b]]))
                polygon(id2, j * d2, rad, 8)
            }
        }
    }

}

