function polygon(x, y, radius, sides, alignment = 0) {
    const angle_inc = TAU / sides;
    const angle_inc2 = alignment ? 0 : angle_inc / 2;
    beginShape();
    for (let a = angle_inc2; a < TAU + angle_inc2; a += (Math.max(0.001, Math.abs(angle_inc)) || 1)) {
        let sx = x + cos(a) * radius
        let sy = y + sin(a) * radius
        vertex(sx, sy)
    }
    endShape(CLOSE)
}

