function neon_spread() {
    noStroke()
    rectMode(CENTER)
    fill(0)
    background(255)

    const n1 = 6 + max(0, int((S - 600) / 300))
    const d2 = S / n1
    const d22 = d2 / 2
    const diam = max(d2 / 10, d2 * 0.565 * mX)
    const diam2 = d2 * 0.71 * mX2
    const spread = d22 * mY
    const rect_length = spread * 2
    const rect_thickness = max(d2 / 15, diam * 0.21)

    for (let i = 0; i <= n1; i++) {
        const id2 = i * d2
        for (let j = 0; j <= n1; j++) {
            const jd2 = j * d2
            if (i % 2 === j % 2) {
                rect(id2, jd2, rect_thickness, rect_length)
                circle(id2 - spread, jd2, diam)
                circle(id2 + spread, jd2, diam)
            }
            else {
                rect(id2, jd2, rect_length, rect_thickness)
                circle(id2, jd2 - spread, diam)
                circle(id2, jd2 + spread, diam)
            }
        }
    }

    push()
    blendMode(LIGHTEST)
    if (fade_timer) fill(255 - 120 * fade_value_norm, 255 - 30 * fade_value_norm, 255, (190 + 65 * fade_value_norm) * mY2)
    else if (revealed) fill(255, 190 * mY2)
    else fill(135, 225, 255, 255 * mY2)

    for (let i = 0; i <= n1; i++) {
        const id2 = i * d2
        for (let j = 0; j <= n1; j++) {
            if (i % 2 === j % 2) {
                push()
                translate(id2, j * d2)
                rotate(QUARTER_PI)
                square(0, 0, diam2)
                pop()
            }
        }
    }
    pop()
}

