function curved_lines_grid() {
    background(200, 150, 0)
    fill(0)
    stroke(0)

    let w = S / 8 //(5 + max(0, int((S-600)/100)));
    let w_mid = w * (0.3 + 0.507 * mX)
    strokeWeight(max(w_mid / 40, 2))
    let h_mid = w * (0.3 + 0.507 * mY)

    let x = 0
    let _wG_12 = 0; while ((x < S) && ++_wG_12 < 20000) {
        wx = w_mid * (0.3 + 0.6 * sin(x / S * PI))
        let y = 0
        let _wG_13 = 0; while ((y < S) && ++_wG_13 < 20000) {
            hy = h_mid * (0.3 + 0.6 * sin(y / S * PI))

            push()
            translate(x, y)
            line(0, 0, wx, hy)
            push()
            noStroke()
            triangle(0, 0, wx * 1.02, 0, 0, hy * 1.02)
            pop()
            pop()

            y += hy
        }

        x += wx
    }
}
