function crooked_lines() {
    background(0)

    let n1 = 5 + max(0, int((S - 600) / 130))
    let rect_size = S / n1
    let factor = (1 - 0.17 * mY)
    let rect_size2 = rect_size * factor
    let diff = rect_size - rect_size2
    let n2 = n1 / factor

    fill(255)
    translate(diff, 2 * diff)

    push()
    for (let j = 0; j < n2; j++) {
        translate(-diff, 0)
        push()
        for (i = 0; i < n2; i++) {
            translate(diff, -diff)
            rect(i * rect_size2, j * rect_size, rect_size2)
        }
        pop()
    }
    pop()

    rectMode(CENTER)
    let opacity = 50 + 80 * map(mX, 0, 1.5, 0, 2)
    let col_list = [[255, 0, 0], [0, 255, 0], [0, 0, 255]]
    let diag = rect_size2 / 4
    let L = 2 * S
    let W = rect_size2 / 5
    let W2 = rect_size2 - 1.5 * W

    let count = 0
    for (let j = 0; j < n2; j++) {
        translate(0, -diff)
        push()
        translate(j * rect_size2 + diag, j * rect_size + diag)
        rotate(QUARTER_PI)
        fill(...col_list[count % col_list.length], opacity)
        count++
        rect(0, 0, W, L)
        translate(W2, W2)
        fill(...col_list[count % col_list.length], opacity)
        count++
        rect(0, 0, W, L)
        pop()
    }
}
