    const inc = (S * 0.995) / grid_size * max(0.1, mY)
    const inc2 = (inc + S * 0.005) / 2
    const diam = inc * 0.9
    const mX_temp = map(mX, 0, 1.5, 5, 1) * (0.025 - 0.015 * mobile) // to scale the dot size
    const d = density * density
    const dg2 = d * d * grid_size2
    const SF4 = SF * 4

    if (initialize_illusion) {
        pg1.resizeCanvas(grid_size2, grid_size2)
        pg1.fill(0)
        pg1.stroke(0)
        const sz = grid_size2 * 0.4
        pg1.textSize(sz)
        pg1.textAlign(CENTER, CENTER)
        pg1.textFont(unibold)
        pg1.background(200)
        pg1.text('HIDE', grid_size22, grid_size22 - sz / 1.2)
        pg1.text('SEEK', grid_size22, grid_size22 + sz / 1.5)
        pg1.noStroke()
        noSmooth()
    }

    pg1.push() // the plus sign
    pg1.rectMode(CENTER)
    pg1.fill(200)
    pg1.translate(grid_size22 * map(mX, 0, 1.5, 0.25, 1.75), grid_size22) // positioning the plus sign
    pg1.rect(0, 0, grid_size2 * 2, grid_size2 / 4.25)
    pg1.fill(0)
    pg1.rect(0, 0, grid_size2 / 15, grid_size2 / 4.5)
    pg1.rect(0, 0, grid_size2 / 4.5, grid_size2 / 15)
    pg1.loadPixels()
    pg1.pop()

    background(255)
    fill(0)
    for (let i = 0; i < grid_size; i++) {
        const x = i * inc + inc2
        for (let j = 0; j < grid_size; j++) {
            const y = j * inc + inc2
            const pix = pg1.pixels[int((i * d + j * dg2) * SF4)]
            const b = (pix < 50)
            circle(x, y, diam * (1 - (mX_temp * b * (1 + 4 * (1 - fade_value_norm)))))
        }
    }
    if (debug) image(pg1, S - grid_size2, 10)
}
