function angled_dango() {
    // could be coded a bit better to avoid some fudge factors, but it's fine.

    background(180, 180, 200)
    rectMode(CENTER)

    let n1 = 5
    let seg_width = S / n1
    let loc_x = seg_width / 2
    let diam = seg_width / (2 + 1.6 * (1.25 - mY))
    let diam_x = diam * (1.05 + 0.25 * mX)
    let diam_y = diam * 1.05
    let diam_shift = diam * 0.20
    let n2 = S / (diam * 2)
    let rect_width = diam * 0.2
    let rect_height = diam * 2 * 0.83
    let angle = atan2(rect_width, diam) * 1.02 * min(1, (mX < 0.6 && mX > 0.4) ? 0.495 : mX)

    for (let i = 0; i < n1; i++) {
        push()
        translate(loc_x, 0)
        loc_x += seg_width
        let loc_y = diam * (1 - i % 2)
        let dir = (i % 2 === 0) ? 1 : -1
        for (j = 0; j < n2 + i % 2; j++) {
            let shift = rect_width / 2 * -dir
            push()
            translate(0, loc_y)
            fill(75, 30, 25)
            ellipse(0, diam / 2, diam_x, diam_y)

            push()
            fill(255, 200, 150)
            ellipse(0, -diam / 2, diam_x, diam_y)
            rotate(dir * angle)
            translate(0, diam_shift)
            translate(-shift, 0)
            rect(0, 0, rect_width, rect_height)
            pop()

            push()
            rotate(dir * angle)
            translate(0, -diam_shift)
            translate(shift, 0)
            rect(0, 0, rect_width, rect_height)
            pop()

            loc_y += diam * 2
            pop()
        }
        pop()
    }
}
