function bent_lines() {
    background(140)
    const n1 = 8 + int(S / 120)
    const seg_width = S / n1

    const line_width = 5
    const final_width = seg_width / 16
    const line_height = S + seg_width * 2

    let loc_x = seg_width / 2 - line_width / 2
    const center_y = -seg_width

    if (initialize_illusion) {
        pg1.resizeCanvas(line_width, line_height)
        pg1.noStroke()
        pg1.translate(0, line_height / 2)
        pg1.fill(0)
        // noSmooth()
    }
    pg1.background(255)

    let vert_shift_amount = seg_width
    const seg_width2 = seg_width * map(mY, 0, 1.5, 0, 2)

    pg1.beginShape()
    pg1.vertex(0, -seg_width * 1.5)
    pg1.vertex(line_width, -seg_width * 1.5 + seg_width2)
    pg1.vertex(line_width, seg_width * 1.5 - seg_width2)
    pg1.vertex(0, seg_width * 1.5)
    pg1.endShape(CLOSE)

    for (let i = 1; i < 3; i++) {
        pg1.push()
        pg1.translate(0, -seg_width * (0.5 + 4 * i))

        pg1.beginShape()
        pg1.vertex(0, -seg_width)
        pg1.vertex(line_width, -seg_width + seg_width2)
        pg1.vertex(line_width, seg_width + seg_width2)
        pg1.vertex(0, seg_width)
        pg1.endShape(CLOSE)

        pg1.pop()
        pg1.push()

        pg1.translate(0, seg_width * (0.5 + 4 * i))

        pg1.beginShape()
        pg1.vertex(0, -seg_width)
        pg1.vertex(line_width, -seg_width - seg_width2)
        pg1.vertex(line_width, seg_width - seg_width2)
        pg1.vertex(0, seg_width)
        pg1.endShape(CLOSE)
        pg1.pop()
    }

    for (let i = 0; i < n1; i++) {
        push()
        const mX_bool = (mX > i / n1)
        translate(loc_x, center_y + mX_bool * vert_shift_amount * (1 - 2 * (i % 2)))
        if (int(i / 2) % 2 === 1 && mX_bool) {
            scale(-1, 1)
            translate(-line_width, 0)
        }
        loc_x += seg_width
        image(pg1, 0, 0, final_width, line_height)
        pop()
    }
}
