function Reutersvärd_triangle() {

    const rt3 = sqrt(3)
    const ts = S * 0.55
    const mX_temp = map(mX, 0, 2, 0.11, 0.315)
    const dw = S * mX_temp
    const dh = 2 / rt3 * dw
    const dh2 = dh / 2
    const dw2 = dw / 2

    pg1.resizeCanvas(dw, dh)

    let col1, col2, col3

    if (revealed) {
        col1 = [255, 64, 0]
        col2 = [0, 255, 64]
        col3 = [0, 64, 255]
        if (mX !== 1.0) pg1.stroke(0)
        else pg1.noStroke()
        background(255, 240, 160)
    }
    else {
        col1 = [160, map(mY, 0, 1.5, 50, 220), 160]
        col2 = [200, map(mY, 0, 1.5, 90, 255), 200]
        col3 = [125, map(mY, 0, 1.5, 30, 175), 125]
        pg1.noStroke()
        const c1 = map(abs(mY - 1), 0, 1, 255, 100)
        const c2 = 60 * (max(mY, 1) - 1)
        background(255 - 4 * c2, c1 + c2, c1 + c2)
    }

    // top rhombus
    pg1.fill(...col1)
    pg1.beginShape()
    pg1.vertex(0, dh2 / 2)
    pg1.vertex(dw / 2, 0)
    pg1.vertex(dw, dh2 / 2)
    pg1.vertex(dw / 2, dh2)
    pg1.endShape(CLOSE)

    // left rhombus
    pg1.fill(...col2)
    pg1.beginShape()
    pg1.vertex(0, dh2 / 2)
    pg1.vertex(dw / 2, dh2)
    pg1.vertex(dw / 2, dh)
    pg1.vertex(0, dh - dh2 / 2)
    pg1.endShape(CLOSE)

    // right rhombus
    pg1.fill(...col3)
    pg1.beginShape()
    pg1.vertex(dw, dh2 / 2)
    pg1.vertex(dw / 2, dh2)
    pg1.vertex(dw / 2, dh)
    pg1.vertex(dw, dh - dh2 / 2)
    pg1.endShape(CLOSE)

    translate(S * 0.42, s)

    const ts2 = ts / 2
    const th = ts * rt3 / 2
    const h2 = ts / rt3
    const h3 = th - h2

    push()
    translate(-dw2, -dh2)

    push()
    translate(h2 / 2, -ts / 6)
    image(pg1, 0, 0)
    pop()

    // right tip
    push()
    translate(h2, 0)
    image(pg1, 0, 0)
    pop()

    push()
    translate(h2 / 2, ts / 6)
    image(pg1, 0, 0)
    pop()

    push()
    translate(0, ts / 3)
    image(pg1, 0, 0)
    pop()

    for (let y = ts2; y > -ts2 - 1; y -= ts / 3) {
        push()
        translate(-h3, y)
        image(pg1, 0, 0)
        pop()
    }

    push()
    translate(0, -ts / 3)
    image(pg1, 0, 0)
    pop()

    // partial shapes
    pg1.clear()
    pg1.fill(...col1)
    pg1.triangle(0, dh2 / 2, dw / 2, 0, dw / 2, dh2)
    pg1.fill(...col2)
    pg1.triangle(0, dh2 / 2, dw / 2, dh2, 0, dh - dh2 / 2)

    push()
    translate(h2 / 2, -ts / 6)
    image(pg1, 0, 0)
    pop()

    pop()

    pg1.clear()
}
