function Adelsons_snake() {
    rectMode(CENTER)
    background(140)

    pg1.fill(120, 255 * mY)
    pg1.resizeCanvas(S, S / 3)
    pg1.noStroke()
    const wavelength = S / 4
    const wave_amp = S * 0.125
    const y_pos = S / 6
    pg1.beginShape();
    pg1.vertex(0, 0);
    pg1.vertex(0, y_pos + wave_amp);
    let dir = 1
    const w4 = wavelength / 4
    for (x = w4; x <= S; x += (Math.max(0.001, Math.abs(wavelength / 2)) || 1)) {
        const y_pos2 = y_pos + wave_amp * dir
        pg1.quadraticVertex(x - w4 / 4, y_pos2, x, y_pos);
        const y_pos3 = y_pos - wave_amp * dir
        pg1.quadraticVertex(x + w4 / 4, y_pos3, x + w4, y_pos3);
        dir *= -1
    }
    pg1.vertex(S, 0);
    pg1.endShape();

    image(pg1, 0, 0)
    image(pg1, 0, int(2 / 3 * S))
    push()
    scale(1, -1)
    translate(0, int(-S * 2 / 3))
    image(pg1, 0, 0)
    pop()

    fill(0, 140 * mX)
    rect(s, S / 3, S, S / 3)
    rect(s, S, S, S / 3)

    translate(s, S / 3)
    const diamond_shade = 93
    fill(diamond_shade)
    const diamond_size = S / 16
    diamond(-wavelength / 2, 0, diamond_size)
    diamond(wavelength / 2, 0, diamond_size)
    translate(wavelength, S / 3)
    diamond(-wavelength, 0, diamond_size)
    diamond(0, 0, diamond_size)

    if (revealed) {
        fill(diamond_shade, 255)
        const d22 = diamond_size * sqrt(2) / 2
        quad(-wavelength + d22, 0,
            -wavelength - d22, 0,
            -wavelength / 2 - d22 - wavelength, -S / 3,
            -wavelength / 2 + d22 - wavelength, -S / 3
        )
    }

    function diamond(x, y, size) {
        push()
        translate(x, y)
        rotate(QUARTER_PI)
        square(0, 0, size)
        pop()
    }
}

