function shaded_diamonds() {
    background(127)

    const dh = S * 2 / 3 * map(mY, 0, 1, 0.25, 1)
    const dh2 = dh / 2
    const dw = S / 6
    const dw2 = dw / 2
    const dsw = dw / 30
    const dsh = dh / 30

    pg1.resizeCanvas(dw, dh)
    if (initialize_illusion) pg1.noStroke()

    //set up diamond shaped masking area
    pg1.push()
    pg1.beginClip()
    pg1.beginShape()
    pg1.vertex(dw2, dh + 1)
    pg1.vertex(dw, dh2)
    pg1.vertex(dw2, -1)
    pg1.vertex(0, dh2)
    pg1.endShape()
    pg1.endClip()

    // top stroke
    pg1.fill(0)
    pg1.beginShape()
    pg1.vertex(dw, dh / 2)
    pg1.vertex(dw / 2, 0)
    pg1.vertex(0, dh / 2)
    pg1.endShape()

    // bottom stroke
    pg1.fill(255)
    pg1.beginShape()
    pg1.vertex(dw, dh2)
    pg1.vertex(dw2, dh)
    pg1.vertex(0, dh2)
    pg1.endShape()

    // middle diamond
    pg1.fill(127.5 * mY2)
    pg1.beginShape()
    pg1.vertex(dw2, dh - dsh)
    pg1.vertex(dw - dsw, dh2)
    pg1.vertex(dw2, dsh)
    pg1.vertex(dsw, dh2)
    pg1.endShape()

    // erase strokes in the middle portion
    pg1.rectMode(CENTER)
    pg1.rect(dw2, dh2, dw * 2, dh * (0.167 + map(mY, 0, 1, 0.12, 0)))

    const blur_amount = dh / 18 * mX * map(mY, 0, 1, 2.2, 1)
    if (blur_amount > 0) pg1.filter(BLUR, blur_amount)

    pg1.pop() // end portion being masked/clipped

    push()
    translate(-dw / 2, -dh / 2)
    const nj = map(mY, 0, 1, 7, 2)

    for (let i = 0; i <= 6; i++) {
        const id2 = i * dw
        for (let j = 0; j < nj; j++) {
            push()
            translate(id2, j * dh)
            image(pg1, 0, 0)
            pop()
        }
    }
    pop()
    for (let i = 0; i <= 6; i++) {
        const id2 = i * dw
        for (let j = 0; j < nj; j++) {
            push()
            translate(id2, j * dh)
            image(pg1, 0, 0)
            pop()
        }
    }

    if (revealed || fade_timer) {
        push()
        fill(0, 255 - fade_value)
        rectMode(CORNERS)
        const sc = map(mY, 0, 1, 1 / 12, 0)
        rect(0, S * (1 / 3 - sc), S, S * (2 / 3 + sc))
        pop()
    }
}

