function Days_sine() {
    background(220, 212, 220)
    stroke(200, 100, 0)
    const angle_norm = TAU / S
    const n1 = (30 + 50 * (S / 600)) * max(0.04, mX2)
    const x_inc = S / n1
    const gap2 = x_inc * 0.75
    const line_height = S * 0.08 * mX
    const sine_height = max(s * min(1, mY) - line_height - 2 * x_inc, 0)

    strokeWeight(x_inc / 2)
    translate(0, s)
    let x_pos = x_inc / 2
    let mid_x = min_y = max_y = 0
    let max_x = s * 0.5
    let min_x = s * 1.5
    let _wG_14 = 0; while ((x_pos < S + x_inc / 2) && ++_wG_14 < 20000) {
        const y_pos = sine_height * Math.sin(x_pos * angle_norm)
        line(x_pos, y_pos + line_height, x_pos, y_pos - line_height)
        push()
        stroke(0, 100, 200)
        line(x_pos, gap2 - s, x_pos, y_pos - line_height - x_inc)
        line(x_pos, y_pos + line_height + x_inc, x_pos, s - gap2)
        pop()
        if (revealed) {
            if (y_pos < min_y) {
                min_x = x_pos
                min_y = y_pos
            }
            if (y_pos > max_y) {
                max_x = x_pos
                max_y = y_pos
            }
            mid_x = abs(s - mid_x) < abs(s - x_pos) ? mid_x : x_pos
        }
        x_pos += x_inc
    }

    if (revealed) {
        noFill()
        stroke(50, 150)
        const diam = line_height * 2
        const y_pos_mid = sine_height * Math.sin(mid_x * angle_norm)
        circle(mid_x, y_pos_mid, diam)
        // const y_pos = sine_height * Math.sin(s/2*angle_norm)
        circle(min_x, min_y, diam)
        circle(max_x, max_y, diam)

        stroke(100, 0, 200)
        line(mid_x, y_pos_mid + diam / 2, mid_x, y_pos_mid - diam / 2)
        line(min_x, min_y + diam / 2, min_x, min_y - diam / 2)
        line(max_x, max_y + diam / 2, max_x, max_y - diam / 2)
    }
}
