function Ponzo() {
    // still room for improvement. At least it scales properly with the window now.
    translate(s, s)
    background(255, 250, 235)

    let L = S / 5
    let horiz = -s * 0.75
    let y_pos1 = -s * 0.525 * mY
    let y_pos2 = s * 0.54 * mY

    strokeWeight(wt / 2)
    strokeCap(ROUND)

    //rails
    stroke(0)
    let L2 = S * 0.002
    let perspective_factor = 0.85
    // let perspective_factor2 = 0.85
    line(-L2, horiz, -s, s)
    line(-L2 * perspective_factor, horiz, -s * perspective_factor, s)
    line(L2, horiz, s, s)
    line(L2 * perspective_factor, horiz, s * perspective_factor, s)

    strokeWeight(wt / 2);
    line(-s, horiz, s, horiz) // horizon line

    // rungs
    let y = s * 1.0
    let y_total = -horiz + s
    let c = s * 0.2
    let y_step = s * 0.2
    let m = y_total / (L + c - L2) / 7.25 // slope
    let rail_wt = S * 0.03
    let _wG_15 = 0; while ((y > horiz + y_step && y_step > S * 0.001) && ++_wG_15 < 20000) {
        y -= y_step
        y_dist = y - horiz
        y_step *= 0.887
        rail_wt *= 0.89
        c2 = c * y_dist / y_total
        let x = m * y_dist + c2
        strokeWeight(rail_wt)
        line(-x, y, x, y)
    }

    // red lines
    strokeWeight(wt * 2);
    stroke(200, 0, 0)
    line(-L, y_pos1, L, y_pos1)
    line(-L, y_pos2, L, y_pos2)
    if (revealed) {
        stroke(200, 0, 0, 180)
        line(-L, y_pos2, -L, y_pos1)
        line(L, y_pos2, L, y_pos1)
    }
}
