function Muller_Lyer_Ponzo() {
    background(240)
    translate(0, s)

    const L = S / 5
    const L2 = L / 2
    const x_shift = 0.25 * (1 - mX)
    const x_pos1 = S * (0.25 + x_shift)
    const x_pos2 = S * (0.75 - x_shift)

    //walls
    const HL1 = L2 * (1 + 2 * mY)
    const y_dev = 2 * abs(mY - 0.5)
    const perspective = 1 - 0.25 * mX * y_dev
    const HW1 = HL1 * map(mY, 1, 0, perspective, 1 / perspective)
    const HL2 = L2 * (3 - 2 * mY)
    const HW2 = HL2 * map(mY, 0, 1, perspective, 1 / perspective)

    strokeWeight(max(1, wt / 4))
    stroke(0, 0, 100, 150)

    fill(200)
    quad(x_pos1, -HL1, x_pos1, HL1, -1, HW1, -1, -HW1)
    quad(x_pos1, -HL1 / 3, x_pos1, HL1 / 3, -1, HW1 / 3, -1, -HW1 / 3)

    push()
    fill(200 - 80 * y_dev)
    quad(x_pos1, -HL1, x_pos1, HL1, x_pos2, HL2, x_pos2, -HL2)
    quad(x_pos1, -HL1 / 3, x_pos1, HL1 / 3, x_pos2, HL2 / 3, x_pos2, -HL2 / 3)
    pop()

    quad(x_pos2, -HL2, x_pos2, HL2, S + 1, HW2, S + 1, -HW2)
    quad(x_pos2, -HL2 / 3, x_pos2, HL2 / 3, S + 1, HW2 / 3, S + 1, -HW2 / 3)

    // wall vertical lines
    const d = 2
    const z_pos1 = d + 4 * (1 - mY)
    const z_pos2 = d + 4 * mY
    const z_range = abs(z_pos1 - z_pos2)
    const z_inc = 8

    const W_width = x_pos2 - x_pos1
    const Wx = W_width / z_inc

    let y_val
    let dir = 1
    if (mY > 0.5) {
        y_val = 2 * mY
        x_start = x_pos1
    }
    else {
        y_val = map(mY, 0, 0.5, 2, 1)
        dir = -1
        x_start = x_pos2
    }

    let x_pos = x_start

    for (let i = 1; i < z_inc; i++) {
        const z_pos = d + z_range * i / z_inc
        const x = Wx * d / z_pos * y_val
        x_pos += dir * x
        const Hx = lerp(HL1, HL2, (x_pos - x_pos1) / W_width)
        line(x_pos, -Hx, x_pos, Hx)
    }

    // x_pos = x_start
    // for(let i = 1; i < 4; i++){
    //     const z_pos = d + 2 * mX * i / 5
    //     const x = x_start/4 * d/z_pos * y_val
    //     x_pos -= dir * x
    //     const Hx = lerp(HL1,HW1, (x_start - x_pos)/x_start)
    //     line(x_pos, -Hx, x_pos, Hx)
    // }

    // red lines
    push()
    strokeWeight(max(3, wt))
    stroke(200, 0, 0)
    line(x_pos1, -L2, x_pos1, L2)
    line(x_pos2, -L2, x_pos2, L2)
    if (revealed) {
        push()
        strokeCap(ROUND)
        line(x_pos1, -L2, x_pos2, -L2)
        line(x_pos1, L2, x_pos2, L2)
        pop()
    }
    pop()
}
