function Poggendorff() {
    background(255, 240, 255)
    strokeWeight(wt * 2.2)
    let d1 = s
    let angle = PI * 0.85 * mY
    let rect_width = d1 * (0.12 + 0.22 * mX)
    translate(s, s)
    rectMode(CENTER)
    push()
    stroke(0)
    let line_offset = -d1 / 14
    push()
    rotate(angle)
    line(0, 0, 0, s)
    stroke(170, 0, 0)
    line(0, -d1, 0, 0)
    stroke(0, 0, 170)
    line(line_offset, d1 * 0.07, line_offset, -d1)
    pop()
    pop()

    let gradient = drawingContext.createLinearGradient(-rect_width / 2, 0, rect_width / 2, 0)
    const fade_value2 = (revealed || fade_timer) ? map(fade_value, 0, 255, 150, 255) : 255
    gradient.addColorStop(0, color(0, fade_value2))
    gradient.addColorStop(0.5, color(235, fade_value2))
    gradient.addColorStop(1, color(0, fade_value2))
    drawingContext.fillStyle = gradient
    rect(0, 0, rect_width, S * 0.9)
}
