// %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

function Hering() {
    background(255, 230, 255)
    translate(s, s)
    push()
    stroke(0, 0, 150)

    const angle_gap = PI / 14
    const end_angle = (PI - angle_gap) / 2
    let angle_increment = end_angle / 15
    let angle = 0
    for (let i = 0; i <= 25 * mY; i++) {
        push()
        rotate(angle)
        line(-S, 0, S, 0)
        rotate(-2 * angle)
        line(-S, 0, S, 0)
        pop()
        angle += angle_increment
        angle_increment *= 0.95
    }
    pop()
    stroke(200, 0, 0)
    const line_spacing = S / 10 * mX
    line(-line_spacing, -S, -line_spacing, S)
    line(line_spacing, -S, line_spacing, S)
}
// %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
// %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

function Ebbinghaus() { // aka Titchener circles

    background(245)
    translate(s, s)
    let center_col = color(220, 140, 30)
    let diam1 = S / 9
    let diam2 = diam1 * map(mX, 0, 1, 1 / 3, 2)
    let diam3 = diam1 / 3

    fill(175, 175, 220, mY * 255)
    push()
    const dist1 = S * 0.11
    const x_pos = diam1 * 2 * map(mX, 0, 1, 0.375, 1.06)

    const coord1 = [-x_pos + dist1, x_pos - dist1]

    translate(...coord1)

    push()
    fill(center_col)
    circle(0, 0, diam1)
    pop()

    for (let i = 0; i < 6; i++) {
        const angle = PI / 3 * i
        const x = x_pos * cos(angle)
        const y = x_pos * sin(angle)

        circle(x, y, diam2)
    }
    pop()

    const dist2 = S * 0.28
    push()
    translate(dist2, -dist2)

    push()
    fill(center_col)
    circle(0, 0, diam1)
    pop()
    const x_pos2 = (diam1 + diam3) * 0.55
    for (let i = 0; i < 8; i++) {
        rotate(QUARTER_PI);
        circle(x_pos2, 0, diam3)
    }
    pop()

    center_col.setAlpha(100)
    if (revealed) {
        stroke(center_col)
        strokeWeight(diam1)
        line(...coord1, dist2, -dist2, 20)
    }
}
