function Kanizsa_triangle() {
    const col1 = map(mX2, 0, 1, 20, 245)
    bg_col = color(col1, col1, 255 * mX2)
    background(bg_col)
    fill(bg_col)
    const r = s * 0.75;
    const r_inc = r / (1 + 11 * mX)
    let r2 = s * (0.25 * 3)
    const diam = s * 0.65
    const diam_inc = diam / (1 + 8 * mX)
    const angle_increment = TAU / (3 + revealed)
    const line_col = 245 * (1 - mX2)
    const wtY = wt * mY

    translate(s, s)
    if (!revealed) {
        translate(0, -S * 0.078)
        rotate(angle_increment / 4)
    }

    push()
    stroke(line_col);
    strokeWeight(wtY)
    let _wG_16 = 0; while ((r2 > r / 2) && ++_wG_16 < 20000) {
        beginShape();
        for (let a = 0; a < TAU; a += (Math.max(0.001, Math.abs(angle_increment)) || 1)) vertex(cos(a) * r2, sin(a) * r2);
        endShape(CLOSE);
        r2 -= r_inc
    }
    pop()

    rotate(angle_increment / 2)
    beginShape();
    for (let a = 0; a < TAU; a += (Math.max(0.001, Math.abs(angle_increment)) || 1)) {
        vertex(x = cos(a) * r, y = sin(a) * r);
        push()
        let diam2 = diam
        stroke(line_col);
        strokeWeight(wtY)
        let _wG_17 = 0; while ((diam2 > diam / 40) && ++_wG_17 < 20000) {
            circle(x, y, diam2)
            diam2 -= diam_inc
        }
        pop()
    }
    endShape(CLOSE);
}
