// %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
// %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
// %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
// %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

var illusion_index = 24  // active illusion_index number
var debug = false
var locked_starting_illusion = true
var illusions_total = illusions_array.length // total number of illusions
var illusion, seed, layers, mobile, unibold
var coord_string, title_button_width, button_height
var interactive = false
var canv_mult = 1
var mX, mY, mX2, mY2
var initial_mouseX = -1
var initial_mouseY = -1
var touch_mode = 0
const touch_margin = 0.1
var display_coordinates = true
var revealed = false
var show_info = false
var overlapping_info_box = false

var x_interactive = true
var y_interactive = true
var x1_interactive, y1_interactive, x2_interactive, y2_interactive
var interaction_mode //_1, interaction_mode_2
var interaction_delay_amount = 300 // in milliseconds
var save_name, illusion_name, category
var refresh = false
var final_refresh = false
var initialize_illusion = true // used by some illusion functions to know whether it is the first run 
var refresh_delay // effectively a framerate reducer
var touch_timer = -1
var fade_value = 255
var fade_timer = 0
var fade_value_norm = 1
const fade_duration = 90 // number of frames that the timer counts down after a reveal toggle.
const category_totals = []
const category_indices = []

// %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
// %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
// %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
// %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

function preload() {

	seed = random(10000000)
	mX = mY = mX2 = mY2 = 1
	unibold = loadFont('https://openprocessing.org/sketch/1941150/files/unispace bd.ttf')
	mobile = (min(displayWidth, displayHeight) < 450)
	frameRate(60)

	canv = createCanvas(10, 10)
	pg1 = createGraphics(10, 10)
	pg2 = createGraphics(10, 10)
	pg3 = createGraphics(10, 10)
	mask_layer = createGraphics(10, 10)

	number_button = createButton('NUMB')
	number_button.mousePressed(prev_illusion)
	number_button.id('NUMBER')
	number_button.style('backgroundColor', 'rgb(50,20,18)')
	number_button.style('color', 'rgb(220, 220, 250)')

	title_button = createButton('TITLE')
	title_button.mousePressed(change_illusion)
	title_button.id('TITLE')
	title_button.style('backgroundColor', 'rgb(50,20,18)')
	title_button.style('color', 'rgb(220, 220, 250)')

	interact_button = createButton('INTERACT')
	interact_button.mousePressed(reset_illusion)
	interact_button.id('INTERACT')
	interact_button.style('backgroundColor', 'rgb(50,20,18)')
	interact_button.style('color', 'rgb(220, 220, 250)')
	// interact_button.style('text-align', 'left')

	coord_button = createButton('COORD')
	coord_button.mousePressed(coordinates_toggle)
	coord_button.id('COORD')
	coord_button.style('backgroundColor', 'rgb(50,20,18)')
	coord_button.style('color', 'rgb(220, 220, 250)')

	show_info_button = createButton('info')
	show_info_button.mousePressed(show_info_toggle)
	show_info_button.id('SHOW_INFO')
	show_info_button.style('backgroundColor', 'rgb(50,20,18)')
	show_info_button.style('color', 'rgb(220, 220, 250)')

	reveal_button = createButton('V')
	reveal_button.mousePressed(reveal_toggle)
	reveal_button.id('REVEAL')
	reveal_button.style('backgroundColor', 'rgb(50,20,18)')
	reveal_button.style('color', 'rgb(220, 220, 250)')

	category_button = createButton('category')
	category_button.mousePressed(switch_category)
	category_button.id('CATEGORY')
	category_button.style('backgroundColor', 'rgb(50,20,18)')
	category_button.style('color', 'rgb(220, 220, 250)')

	info_button_top = createButton('i1')
	info_button_top.mousePressed(conditional_show_info_toggle)
	info_button_top.id('INFO1')
	info_button_top.style('backgroundColor', 'rgb(40,38,80)')
	info_button_top.style('color', 'rgb(255, 240, 240)')
	info_button_top.hide()

	info_button_bottom = createButton('i2')
	info_button_bottom.mousePressed(conditional_show_info_toggle)
	info_button_bottom.id('INFO2')
	info_button_bottom.style('backgroundColor', 'rgb(40,38,80)')
	info_button_bottom.style('color', 'rgb(255, 240, 240)')
	info_button_bottom.hide()

	let temp_category = illusions_array[0].category
	let category_illusions_count = 1
	for (i = 1; i < illusions_total; i++) {

		const current_category = illusions_array[i].category

		if (current_category === temp_category) {
			category_illusions_count++
		}
		if (current_category !== temp_category || i === illusions_total - 1) {
			category_totals.push(category_illusions_count)
			category_illusions_count = 1
		}

		temp_category = illusions_array[i].category
	}
	let current_index = 0
	for (i = 0; i < category_totals.length; i++) {
		current_index += category_totals[i]
		category_indices.push((current_index + 1))//% illusions_total)
	}
	// console.log(category_totals)
	// console.log(category_indices)

	// check for URL parameter
	const urlParams = new URLSearchParams(window.location.search);
	if (urlParams.has('illusion')) {
		const illusion_param = urlParams.get('illusion')
		if (illusion_param >= 0 && illusion_param < illusions_total) {
			illusion_index = int(illusion_param)
		}
	}
}

function coordinates_toggle() {
	display_coordinates = !display_coordinates
	if ((illusion.x_range && round(mX, 2) !== 1) || (illusion.y_range && round(mY, 2) !== 1) ||
		(illusion.x2_range && round(mX2, 2) !== 1) || (illusion.y2_range && round(mY2, 2) !== 1)) {
		refresh = true
		final_refresh = true
		redraw()
	}
	if (display_coordinates === false) document.getElementById("COORD").innerHTML = ''
	else document.getElementById("COORD").innerHTML = coord_string
}

function show_info_toggle(update_only = false) {

	if (update_only !== true) show_info = !show_info

	if (show_info) {
		document.getElementById("INFO1").innerHTML = illusion.info1
		document.getElementById("INFO2").innerHTML = illusion.info2
		info_button_top.show()
		if (illusion.info2 || (device_orientation_vertical && !overlapping_info_box)) info_button_bottom.show()
		else info_button_bottom.hide()
	}
	else {
		info_button_top.hide()
		info_button_bottom.hide()
	}
}

function conditional_show_info_toggle() {
	if (overlapping_info_box) show_info_toggle()
}

// %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
// %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
// %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
// %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

function setup(random_selection = !locked_starting_illusion, density_setting = 0, reset_illusion = false) {
	S = max(windowWidth, windowHeight)
	s = S / 2
	if (density_setting > 0) pixelDensity(density_setting)
	else if (canv_mult > 1) {
		let canv_max = 10000 // pixels 
		let canv_mult_max = min(canv_max / S, canv_mult)
		// for a non-square canvas, use: let canv_mult_max = min(canv_max/max(windowWidth,windowHeight), canv_mult) 
		pixelDensity(canv_mult_max)
	}
	else pixelDensity(min(2, displayDensity()))

	density = pixelDensity()

	resizeCanvas(S, S)
	device_orientation_vertical = (windowHeight > S)

	const button_height_min = round(S * 0.07)
	const button_height_max = round(S * 0.14)
	const text_size_max = round(S * 0.08)
	const S_max = max(windowWidth, windowHeight)
	const S_margin = (S_max - S) / 2
	button_height = min(S_margin, button_height_max)
	const text_size = round(min(button_height, text_size_max) * 0.8)
	const button_width = max(button_height * 0.8, text_size * 2.5)
	const text_size_str = text_size + "px"
	const text_size_str2 = device_orientation_vertical ? text_size + "px" : button_height * 0.45 + "px"
	// const text_size_strV = device_orientation_vertical? text_size + "px" : button_width*0.45 + "px"

	const margin_diff = S_margin - button_height

	// const text_size = button_height * 0.88 + "px"
	number_button.style("font-size", button_width * 0.5 + "px")
	title_button.style("font-size", button_width * 0.35 + "px")
	reveal_button.style("font-size", text_size_str)
	category_button.style("font-size", min(button_width * 0.35, button_height * 0.5) + "px")
	const min_button_height = S / 4
	info_button_top.style("font-size", min_button_height / 4 + "px")
	info_button_bottom.style("font-size", min_button_height / 4 + "px")

	interact_button.style("font-size", device_orientation_vertical ? button_height * 0.45 + "px" : button_width * 0.45 + "px")
	coord_button.style("font-size", button_height * 0.45 + "px")
	show_info_button.style("font-size", text_size_str2)


	if (button_height < button_height_min) {
		number_button.hide()
		title_button.hide()
		interact_button.hide()
		coord_button.hide()
		show_info_button.hide()
		reveal_button.hide()
		category_button.hide()

		button_zone = 0
	}
	else {
		number_button.show()
		title_button.show()
		interact_button.show()
		coord_button.show()
		show_info_button.show()
		reveal_button.show()
		category_button.show()

		button_zone = button_height

		const info_button_height = max(min_button_height, windowHeight - S - S_margin - button_height)
		overlapping_info_box = (windowHeight - 2 * info_button_height < S + button_height * 1.35)

		if (device_orientation_vertical) {
			number_button.size(button_width * 1.25, button_height - 3)
			number_button.position(0, margin_diff)

			title_button_width = S - button_width * 1.25
			title_button.size(title_button_width, button_height - 3)
			title_button.position(button_width * 1.25, margin_diff)
			title_button.style('transform', 'rotate(0deg)')

			interact_button.size(button_width, button_height + 3)
			interact_button.position(0, windowHeight - S_margin - 3)

			coord_button.size(button_width * 1.15, button_height + 3)
			coord_button.position(button_width, windowHeight - S_margin - 3)

			show_info_button.size(button_width, button_height + 3)
			show_info_button.position(S - 2 * button_width, windowHeight - S_margin - 3)

			reveal_button.size(button_width, button_height + 3)
			reveal_button.position(S - button_width, windowHeight - S_margin - 3)

			category_button.size(S - 4.15 * button_width, button_height + 3)
			category_button.position(2.15 * button_width, windowHeight - S_margin - 3)
			category_button.style('transform', 'rotate(0deg)')

			info_button_top.size(S, info_button_height)
			info_button_top.position(0, 0)
			info_button_bottom.size(S, info_button_height)
			info_button_bottom.position(0, windowHeight - info_button_height)

		}
		else {
			number_button.size(button_height, button_width)
			number_button.position(margin_diff, S - button_width)

			title_button_width = int(S - button_width - button_height)
			title_button.size(title_button_width + button_height, button_height)
			title_button.position(margin_diff - title_button_width / 2, title_button_width / 2)
			title_button.style('transform', 'rotate(270deg)')

			interact_button.size(button_height, button_width * 1.1)
			interact_button.position(windowWidth - S_margin, S - button_width * 1.1)

			coord_button.size(button_height, button_width)
			coord_button.position(windowWidth - S_margin, S - 2.1 * button_width)

			show_info_button.size(button_height, button_width * 1.1)
			show_info_button.position(windowWidth - S_margin, button_width)

			reveal_button.size(button_height, button_width)
			reveal_button.position(windowWidth - S_margin, 0)

			const category_button_width = S - int(4.2 * button_width)
			category_button.size(category_button_width, button_height)
			category_button.position(windowWidth / 2 + s - category_button_width / 2 + button_height / 2, s - button_height * 0.5)
			category_button.style('transform', 'rotate(270deg)')

			info_button_top.size(S, min_button_height)
			info_button_bottom.size(S, min_button_height)
			const x_pos = windowWidth - S - S_margin
			info_button_top.position(x_pos, 0)
			info_button_bottom.position(x_pos, windowHeight - min_button_height)
		}
	}

	t = 0
	wt = S * 0.005
	strokeWeight(wt)

	stroke(255)
	textAlign(CENTER, BOTTOM)
	wt2 = wt * 6 * (1 + (S < 1000))
	textSize(wt2)
	if (reset_illusion) {
		mX = mY = mX2 = mY2 = 1
		initialize_illusion = false
	}
	else {
		initialize_illusion = true
	}
	if (random_selection && !debug) illusion_index = int(random(illusions_total) + 1)  // randomize starting point for final version?
	final_refresh = true
	illusionPicker(illusion_index)
	init_illusion()
}

// %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
// %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
// %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
// %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

function draw() {
	if (touch_mode !== 0) {
		if (touch_timer >= 0) touch_timer--
		if (touch_timer === 0 && touch_mode === touches.length) touch_commands(touch_mode)
	}
	if (refresh) illusionPicker(illusion_index) // required to refresh when mX or mY are changed when mouse is dragged
	if (fade_timer > 0) fade_operation()
	else {
		refresh = false
		final_refresh = false
	}
}

function fade_operation() {
	fade_timer--
	// fade_ratio = fade_timer/fade_duration
	fade_value = revealed ? max(0, fade_value - 3) : min(fade_value + 3, 255)
	fade_value_norm = fade_value / 255
	// console.log(fade_timer, fade_value_norm)
	// fade_value = revealed? fade_ratio * 255 : (1 - fade_ratio) * 255
}

function reveal_toggle() {
	if (illusion.revealable === false) return
	revealed = !revealed
	if (revealed) reveal_button.style('backgroundColor', 'rgb(0,60,60)')
	else reveal_button.style('backgroundColor', 'rgb(50,20,18)')
	if (illusion.fade_reveal) {
		fade_timer = fade_duration
		refresh = true
	}
	else final_refresh = true
	illusionPicker(illusion_index)
}

function keyPressed() {
	if (key === 's') save_img()
	else if (key === 'f') {
		if (fullscreen()) fullscreen(false)
		else go_fullscreen()
	}
	else if (key === 'r') {
		setup(false, density, true) // reset to default positions
	}
	else if (key === 'd' && !((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) {
		debug = !debug
		illusionPicker(illusion_index)
	}
	else if (key === 'v') {
		reveal_toggle()
	}
	else if (key === 'i') show_info_toggle()
	else if (key === 'c') coordinates_toggle()
	else if (key === ' ' || keyCode === RIGHT_ARROW) change_illusion(direction = 1)
	else if (keyCode === LEFT_ARROW) change_illusion(direction = -1)
	else {
		let num = int(key);
		if (num >= 1 && num <= 9) {
			canv_mult = (num + 1) / 2
			setup(false)
		}
	}
}

function touchStarted() { input_pressed() }
function touchEnded() { input_released() }
function touchMoved() { input_dragged() }
function mousePressed() { input_pressed() }
function mouseReleased() { input_released() }
function mouseDragged() { input_dragged() }

function go_fullscreen() {
	if (fullscreen()) return
	fullscreen(true)
}

document.addEventListener("contextmenu", (event) => event.preventDefault(), "true")
document.addEventListener("touchStarted", (event) => event.stopPropagation(), "true")
document.addEventListener("touchEnded", (event) => event.stopPropagation(), "true")
document.addEventListener("touchMoved", (event) => event.stopPropagation(), "true")
document.addEventListener("touchmove", (event) => event.preventDefault(), { passive: false })

function input_pressed() {
	touch_mode = touches.length
	if (touch_mode > 0) {
		interaction_delay_amount = 250
		if (touch_mode >= 3) touch_timer = 30  // number of frames needed to hold for long press
		else touch_timer = 2 // number of frames needed to hold for short press (the time allocated to get all the fingers in contact)
	}
	else {
		interaction_delay_amount = 0
		// if(mouseButton === CENTER) reset_illusion()
	}

	initial_mouseX = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))
