function input_dragged() {
	// console.log(valid_interaction())
	if (!valid_interaction()) return
	if (refresh_delay > 0) refresh_delay--
	else if (millis() - switch_time > interaction_delay_amount) {

		switch (interaction_mode) {
			case 1:
				const [mX_temp, mY_temp] = mXY_update(illusion.x_range, illusion.y_range)
				if (mX_temp != -1) mX = mX_temp
				if (mY_temp != -1) mY = mY_temp
				break
			case 2:
				const [mX_temp2, mY_temp2] = mXY_update(illusion.x2_range, illusion.y2_range)
				if (mX_temp2 != -1) mX2 = mX_temp2
				if (mY_temp2 != -1) mY2 = mY_temp2
		}

		if (interactive) { // check whether it is interactive before refreshing
			if (canv_mult > 1) {
				canv_mult = 1
				setup(false)
			}
			refresh = true
		}
	}
}

function input_released() {
	if (interactive && valid_interaction()) { //millis() - switch_time > 200){
		refresh = true
		final_refresh = true
	}
}
