function change_illusion(direction = 1, increment = 1) {
	initialize_illusion = true
	mX = mY = mX2 = mY2 = 1
	strokeCap(SQUARE)
	rectMode(CORNER)
	pg1.rectMode(CORNER)
	pg2.rectMode(CORNER)
	pg3.rectMode(CORNER)
	mask_layer.rectMode(CORNER)
	smooth()

	if (direction === -1) {
		illusion_index--
		if (illusion_index < 1) illusion_index = illusions_total
	}
	else {
		illusion_index += increment
		if (illusion_index > illusions_total) illusion_index = 1
	}
	loop()
	final_refresh = true
	revealed = false
	const previous_density = density
	// if(illusion_index === 5 || illusion_index === 9) final_refresh = false // need to make this update automatically
	illusionPicker(illusion_index)
	if (density != previous_density) setup(false, density)
	init_illusion()
}

function switch_category() {
	let next_category_index = 0
	for (i = 0; i < category_totals.length; i++) {
		if (illusion_index < category_indices[i]) {
			next_category_index = category_indices[i]
			break
		}
	}
	const increment_amount = next_category_index - illusion_index
	change_illusion(direction = 1, increment = increment_amount)
}

function init_illusion() {
	interaction_mode = 0
	fade_timer = 0
	fade_value = 255
	fade_value_norm = 1
	const title = illusion.name
	document.getElementById("TITLE").innerHTML = title
	// console.log(title_button_width)
	title_button.style("font-size", button_height * min(0.6, 11 / title.length) + "px")
	document.getElementById("REVEAL").innerHTML = illusion.revealable ? 'V' : '_'
	document.getElementById("CATEGORY").innerHTML = 'category: ' + illusion.category
	document.getElementById("NUMBER").innerHTML = str(illusion_index)
	reveal_button.style('backgroundColor', 'rgb(50,20,18)')
	switch_time = millis()
	x1_interactive = illusion.x_range > 0
	y1_interactive = illusion.y_range > 0
	x2_interactive = illusion.x2_range > 0
	y2_interactive = illusion.y2_range > 0
	update_interact_info(true)
	show_info_toggle(update_only = true)
}

function update_interact_info(init = false, x = x1_interactive, y = y1_interactive, x2 = x2_interactive, y2 = y2_interactive) {
	if (touch_mode < 3) {
		let x_letter, y_letter

		if (interaction_mode == 0) {
			x_letter = x ? (x2 ? 'x2' : 'x1') : '__'
			y_letter = y ? (y2 ? 'y2' : 'y1') : '__'
		}
		else if (interaction_mode == 1) {
			x_letter = x ? 'x1' : '__'
			y_letter = y ? 'y1' : '__'
		}
		else {
			x_letter = x && x2 ? 'x2' : '__'
			y_letter = y && y2 ? 'y2' : '__'
		}

		const interact_str = x_letter + '<br>' + y_letter
		document.getElementById("INTERACT").innerHTML = interact_str

		if (init && display_coordinates) {
			let x_coord = '1.00'
			let y_coord = '1.00'
			if (x_letter === '__') x_coord = '___'
			if (y_letter === '__') y_coord = '___'
			const coord_str = x_coord + '<br>' + y_coord
			document.getElementById("COORD").innerHTML = coord_str
		}
	}
}

function prev_illusion() {
	change_illusion(-1)
}

function reset_illusion() {
	switch_time = millis()
	setup(false, density, true)
}

