function illusionPicker(n, saving = false) {
	resetMatrix() // clears rotations and translations and such
	t = 0
	interactive = !saving
	comment = ''
	refresh_delay = 0

	push() // do it once here, rather than in each one
	noStroke()
	illusion = illusions_array[n - 1]
	illusion.fn() // run the illusion_index function and draw it
	pop()

	if (saving) {
		saveCanvas(save_name, "png")
		interactive = true
	}
	let x_pos = 0
	let y_pos = 0
	if (display_coordinates || debug) {
		if (interactive && touch_mode < 3) {
			// indicator marks
			push()
			noStroke(0)
			let diam = S * 0.03
			if (x_interactive) {
				const [mX_temp, range] = interaction_mode == 1 ? [mX, illusion.x_range] : [mX2, illusion.x2_range]
				const mX_disp = (mX_temp > 1) ? 2 * (mX_temp - 1) : 1 - mX_temp
				fill(155 - 100 * (1 - mX_temp), 0, 155 + 100 * (1 - mX_temp), 200 * abs(mX_disp))
				x_pos = S * (touch_margin + map(mX_temp, 0, range, 0, 1 - 2 * touch_margin))
				if (display_coordinates) {
					circle(x_pos, 0, diam)
					circle(x_pos, S, diam)
					coord_string = nf(mX_temp, 0, 2) + '<br>'
				}
			}
			else coord_string = '___<br>'
			if (y_interactive) {
				const [mY_temp, range] = interaction_mode == 1 ? [mY, illusion.y_range] : [mY2, illusion.y2_range]
				const mY_disp = (mY_temp > 1) ? 2 * (mY_temp - 1) : 1 - mY_temp
				y_pos = S * (touch_margin + map(mY_temp, 0, range, 0, 1 - 2 * touch_margin))
				fill(155 - 100 * (1 - mY_temp), 0, 155 + 100 * (1 - mY_temp), 200 * abs(mY_disp))
				if (display_coordinates) {
					circle(0, y_pos, diam)
					circle(S, y_pos, diam)
					coord_string += nf(mY_temp, 0, 2)
				}
			}
			else coord_string += '___'
			if ((saving || debug) && x_pos > 0 && y_pos > 0) {
				fill(255, 0, 0, 100)
				circle(x_pos, y_pos, 15)
			}
			pop()
			if (display_coordinates) document.getElementById("COORD").innerHTML = coord_string
		}
	}
	initialize_illusion = false
}

